function tempFromLevel(level, variance = 0) {
  if (level === 0) return 20 + variance;
  if (level === 1) return 25 + variance;
  return 30 + variance;
}

function tempLabel(tempC) {
  if (tempC < 24) return { range: "Normal",   color: "#22c55e", bg: "#052e16" };
  if (tempC < 27) return { range: "Moderate", color: "#f97316", bg: "#431407" };
  return              { range: "High",     color: "#ef4444", bg: "#450a0a" };
}

function computeRoomPosition(existing, rW, rL) {
  const sx = -BUILDING_W/2 + WALL_T + 4 + rW/2;
  const sz = -BUILDING_L/2 + WALL_T + 4 + rL/2;
  const mx = BUILDING_W/2 - WALL_T - 4;
  if (!existing.length) return { x: sx, z: sz };
  const last = existing[existing.length-1];
  const lastZ = last.z;
  const row = existing.filter(r => Math.abs(r.z - lastZ) < 1);
  const rowMaxX = Math.max(...row.map(r => r.x + r.w/2));
  const rowMaxL = Math.max(...row.map(r => r.l));
  const nx = rowMaxX + ROOM_GAP + rW/2;
  if (nx + rW/2 <= mx) return { x: nx, z: lastZ - rowMaxL/2 + rL/2 };
  return { x: sx, z: lastZ + rowMaxL/2 + ROOM_GAP + rL/2 };
}

